\mathrm{df\text{-}field\text{-}embedding}\vdash\;\begin{aligned}
\mathsf{Emb}(\mathcal K,\mathcal L,h)&\leftrightarrow\mathsf{Field}(\mathcal K)\land\mathsf{Field}(\mathcal L)\land\mathsf{Inj}(h,K,L)\\
&\quad\land h(0_K)=0_L\land h(1_K)=1_L\\
&\quad\land\forall a,b\in K\;[h(a+_Kb)=h(a)+_Lh(b)\land h(a\cdot_Kb)=h(a)\cdot_Lh(b)\land h(-_Ka)=-_Lh(a)],\\
\mathsf{Iso}(\mathcal K,\mathcal L,h)&\leftrightarrow\mathsf{Emb}(\mathcal K,\mathcal L,h)\land\forall b\in L\exists a\in K\;h(a)=b.
\end{aligned}
